#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""Stock Scanner Bot - single-file edition.

A US-equities scanner with a browser dashboard and Telegram alerts.
This file is auto-generated by consolidating the multi-file project.

Setup:
    pip install fastapi "uvicorn[standard]" yfinance pandas numpy APScheduler requests lxml

Run:
    python stock_scanner_app.py

Then open http://127.0.0.1:8000 in a browser.

Notes:
    - config.json and a _cache/ folder are created next to this file.
    - Everything (dashboard, styles, charts library) is bundled in this file.
"""


# ============================ config ============================
