def _read_cache(name):
    path = os.path.join(CACHE_DIR, name + ".json")
    if os.path.exists(path) and (time.time() - os.path.getmtime(path)) < UNIVERSE_CACHE_TTL:
        try:
            with open(path, encoding="utf-8") as fh:
                data = json.load(fh)
            if isinstance(data, list) and data:
                return data
        except (json.JSONDecodeError, OSError):
            pass
    return None


def _write_cache(name, tickers):
    try:
        os.makedirs(CACHE_DIR, exist_ok=True)
        with open(os.path.join(CACHE_DIR, name + ".json"), "w", encoding="utf-8") as fh:
            json.dump(tickers, fh)
    except OSError:
        pass


def _normalize(symbols):
    """Yahoo Finance uses '-' where exchanges use '.' (e.g. BRK-B)."""
    out = []
    for sym in symbols:
        sym = str(sym).strip().upper().replace(".", "-")
        if sym and sym != "NAN":
            out.append(sym)
    return out


def get_sp500():
    cached = _read_cache("sp500")
    if cached:
        return cached
    try:
        import pandas as pd

        tables = pd.read_html(SP500_URL)
        tickers = _normalize(tables[0]["Symbol"].tolist())
        if tickers:
            _write_cache("sp500", tickers)
            return tickers
    except Exception:
        pass
    return list(FALLBACK_SP500)


def get_nasdaq100():
    cached = _read_cache("nasdaq100")
    if cached:
        return cached
    try:
        import pandas as pd

        tables = pd.read_html(NASDAQ100_URL)
        for table in tables:
            ticker_cols = [c for c in table.columns if "Ticker" in str(c)]
            if ticker_cols:
                tickers = _normalize(table[ticker_cols[0]].tolist())
                if len(tickers) > 50:
                    _write_cache("nasdaq100", tickers)
                    return tickers
    except Exception:
        pass
    return list(FALLBACK_NASDAQ100)


def resolve_universe(universe_cfg):
    """Return the list of tickers for the configured universe."""
    kind = (universe_cfg or {}).get("type", "sp500")
    if kind == "custom":
        raw = universe_cfg.get("custom_tickers", [])
        return _normalize(raw)
    if kind == "nasdaq100":
        return get_nasdaq100()
    if kind == "both":
        return sorted(set(get_sp500()) | set(get_nasdaq100()))
    return get_sp500()

# ============================ data ============================
"""Market data layer: batch downloads from Yahoo Finance with a short cache."""
import time

import pandas as pd
import yfinance as yf

# timeframe -> (history period, yfinance interval)
TF_MAP = {
    "15m": ("60d", "15m"),
    "30m": ("60d", "30m"),
    "60m": ("720d", "60m"),
    "1h": ("720d", "60m"),
    "1d": ("3y", "1d"),
    "1wk": ("8y", "1wk"),
    "1mo": ("max", "1mo"),
}

_OHLCV = ["Open", "High", "Low", "Close", "Volume"]

_cache = {}            # (timeframe, tickers_key) -> (timestamp, data)
DATA_CACHE_TTL = 900        # 15 minutes


def _clean(df):
    df = df.dropna(how="all")
    df = df[[c for c in _OHLCV if c in df.columns]]
    return df.dropna()


def fetch(tickers, timeframe):
    """Download one timeframe for all tickers. Returns {ticker: DataFrame}."""
    period, interval = TF_MAP.get(timeframe, ("3y", "1d"))
    tickers = list(tickers)
    if not tickers:
        return {}
    raw = yf.download(
        tickers,
        period=period,
        interval=interval,
        group_by="ticker",
        auto_adjust=True,
        threads=True,
        progress=False,
    )
    result = {}
    if raw is None or raw.empty:
        return result
    multi = isinstance(raw.columns, pd.MultiIndex)
    for ticker in tickers:
        try:
            sub = raw[ticker] if multi else raw
        except KeyError:
            continue
        sub = _clean(sub)
        if len(sub) > 0:
            result[ticker] = sub
    return result


def get_data(tickers, timeframe, use_cache=True):
    """Cached wrapper around fetch()."""
    key = (timeframe, tuple(sorted(tickers)))
    now = time.time()
    if use_cache and key in _cache:
        stamp, data = _cache[key]
        if now - stamp < DATA_CACHE_TTL:
            return data
    data = fetch(tickers, timeframe)
    _cache[key] = (now, data)
    return data


def clear_cache():
    _cache.clear()

# ============================ indicators ============================
"""Technical / ICT-style indicator checks.

Every check returns a tuple: (passed: bool, detail: str).
The `detail` string is shown in the dashboard so the user can see *why*
a stock did or did not pass.
"""
import pandas as pd


# --------------------------------------------------------------------------
# Moving averages
# --------------------------------------------------------------------------
def moving_average(series, ma_type, period):
    if str(ma_type).upper() == "EMA":
        return series.ewm(span=period, adjust=False).mean()
    return series.rolling(period).mean()


def check_price_vs_ma(df, ma_type, period, condition):
    """Price above / below a moving average."""
    if len(df) < period:
        return False, "not enough data"
    ma = moving_average(df["Close"], ma_type, period)
    price = float(df["Close"].iloc[-1])
    ma_val = ma.iloc[-1]
    if pd.isna(ma_val):
        return False, "MA n/a"
    ma_val = float(ma_val)
    above = price > ma_val
    ok = above if condition == "above" else not above
    sign = ">" if above else "<="
    return ok, f"price {price:.2f} {sign} {ma_type}{period} {ma_val:.2f}"


def check_ma_cross(df, ma_type, fast_period, slow_period, direction, within_bars):
    """Golden / death cross within the last `within_bars` bars."""
    if len(df) < slow_period + within_bars + 2:
        return False, "not enough data"
    fast = moving_average(df["Close"], ma_type, fast_period)
    slow = moving_average(df["Close"], ma_type, slow_period)
    diff = fast - slow
    prev = diff.shift(1)
    cross_up = (prev <= 0) & (diff > 0)
    cross_down = (prev >= 0) & (diff < 0)
    window = max(1, within_bars)
    if direction == "golden":
        ok = bool(cross_up.iloc[-window:].any())
        return ok, "golden cross" if ok else "no golden cross"
    ok = bool(cross_down.iloc[-window:].any())
    return ok, "death cross" if ok else "no death cross"


def check_price_near_ma(df, ma_type, period, tolerance_pct):
    """Price within `tolerance_pct` of a moving average (dynamic S/R touch)."""
    if len(df) < period:
        return False, "not enough data"
    ma = moving_average(df["Close"], ma_type, period)
    price = float(df["Close"].iloc[-1])
    ma_val = ma.iloc[-1]
    if pd.isna(ma_val) or float(ma_val) == 0:
        return False, "MA n/a"
    dist = abs(price - float(ma_val)) / float(ma_val) * 100
    ok = dist <= tolerance_pct
    return ok, f"{dist:.2f}% from {ma_type}{period}"


# --------------------------------------------------------------------------
# Fair Value Gaps (FVG)
# --------------------------------------------------------------------------
def find_fvgs(df, direction):
    """Three-candle Fair Value Gaps for the given direction.

    Bullish FVG: gap between candle[i-2].high and candle[i].low.
    Bearish FVG: gap between candle[i].high and candle[i-2].low.
    A gap is 'filled' once later price trades fully back through it.
    """
    highs = df["High"].values
    lows = df["Low"].values
    n = len(df)
    fvgs = []
    for i in range(2, n):
        if direction == "bullish" and highs[i - 2] < lows[i]:
            bottom, top = float(highs[i - 2]), float(lows[i])
            filled = bool((lows[i + 1:] <= bottom).any()) if i + 1 < n else False
            fvgs.append({"idx": i, "bottom": bottom, "top": top, "filled": filled})
        elif direction == "bearish" and lows[i - 2] > highs[i]:
            bottom, top = float(highs[i]), float(lows[i - 2])
            filled = bool((highs[i + 1:] >= top).any()) if i + 1 < n else False
            fvgs.append({"idx": i, "bottom": bottom, "top": top, "filled": filled})
    return fvgs


def check_fvg(df, direction, condition, lookback):
    if len(df) < 3:
        return False, "not enough data"
    sub = df.tail(max(lookback, 3))
    open_fvgs = [f for f in find_fvgs(sub, direction) if not f["filled"]]
    if condition == "exists":
        ok = len(open_fvgs) > 0
        return ok, f"{len(open_fvgs)} open {direction} FVG"
    # condition == "price_inside"
    price = float(df["Close"].iloc[-1])
    inside = [f for f in open_fvgs if f["bottom"] <= price <= f["top"]]
    if inside:
        return True, f"price inside {direction} FVG"
    return False, f"price outside FVG ({len(open_fvgs)} open)"


# --------------------------------------------------------------------------
# Range / Equilibrium  (auto dealing range from swing structure)
# --------------------------------------------------------------------------
def dealing_range(df, swing_strength, max_lookback):
    """The current dealing range: most recent significant swing low & high.

    Unlike a fixed window's max/min, this locks onto the actual swing
    structure, so the range adapts whether the leg spans 20, 30 or 60 bars.
    `swing_strength` controls how significant a swing must be (bars each side).
    """
    sub = df.tail(max_lookback)
    is_high, is_low = _swing_points(sub, swing_strength)
    high_pos = [i for i in range(len(sub)) if bool(is_high.iloc[i])]
    low_pos = [i for i in range(len(sub)) if bool(is_low.iloc[i])]
    if not high_pos or not low_pos:
        return None
    hp, lp = high_pos[-1], low_pos[-1]
    high = float(sub["High"].iloc[hp])
    low = float(sub["Low"].iloc[lp])
    if high <= low:
        return None
    return {
        "high": high, "low": low, "eq": (high + low) / 2,
        "high_time": sub.index[hp], "low_time": sub.index[lp],
    }


def eq_band(dr, eq_band_pct):
    """Price bounds of the equilibrium band around the 50% level."""
    span = dr["high"] - dr["low"]
    return (dr["low"] + (50 - eq_band_pct) / 100 * span,
            dr["low"] + (50 + eq_band_pct) / 100 * span)


def check_range(df, swing_strength, max_lookback, zone, eq_band_pct,
                eq_match="close"):
    if len(df) < 2 * swing_strength + 2:
        return False, "not enough data"
    dr = dealing_range(df, swing_strength, max_lookback)
    if dr is None:
        return False, "no clear range"
    candle = df.iloc[-1]
    price = float(candle["Close"])
    pos_pct = (price - dr["low"]) / (dr["high"] - dr["low"]) * 100
    detail = (f"range {dr['low']:.2f}-{dr['high']:.2f} "
              f"pos {pos_pct:.0f}% (EQ {dr['eq']:.2f})")
    if zone == "discount":
        return price < dr["eq"], detail
    if zone == "premium":
        return price > dr["eq"], detail
    # equilibrium
    band_lo, band_hi = eq_band(dr, eq_band_pct)
    if eq_match == "touch":
        ok = float(candle["Low"]) <= band_hi and float(candle["High"]) >= band_lo
        return ok, detail + (" (EQ touched)" if ok else " (EQ not touched)")
    ok = abs(pos_pct - 50) <= eq_band_pct
    return ok, detail


# --------------------------------------------------------------------------
# Liquidity (ICT internal / external)
# --------------------------------------------------------------------------
def _swing_points(df, strength):
    """Boolean masks for swing highs and swing lows.

    A larger `strength` yields fewer, more significant swings (external
    liquidity); a smaller one yields minor swings (internal liquidity).
    """
    window = 2 * strength + 1
    roll_high = df["High"].rolling(window, center=True).max()
    roll_low = df["Low"].rolling(window, center=True).min()
    is_high = df["High"] == roll_high
    is_low = df["Low"] == roll_low
    return is_high, is_low


def check_liquidity(df, strength, lookback, condition, recency=5):
    if len(df) < 2 * strength + 2:
        return False, "not enough data"
    sub = df.tail(lookback).reset_index(drop=True)
    is_high, is_low = _swing_points(sub, strength)
    highs = sub["High"]
    lows = sub["Low"]
    price = float(sub["Close"].iloc[-1])
    n = len(sub)

    untapped_above = untapped_below = swept_above = swept_below = False

    for pos in highs.index[is_high]:
        val = float(highs.iloc[pos])
        later = highs.iloc[pos + 1:]
        exceeded = later[later > val]
        if val > price and exceeded.empty:
            untapped_above = True
        if not exceeded.empty and exceeded.index[0] >= n - recency:
            swept_above = True

    for pos in lows.index[is_low]:
        val = float(lows.iloc[pos])
        later = lows.iloc[pos + 1:]
        breached = later[later < val]
        if val < price and breached.empty:
            untapped_below = True
        if not breached.empty and breached.index[0] >= n - recency:
            swept_below = True

    flags = {
        "untapped_above": untapped_above,
        "untapped_below": untapped_below,
        "swept_above": swept_above,
        "swept_below": swept_below,
    }
    ok = flags.get(condition, False)
    return ok, f"{condition} = {ok}"


# --------------------------------------------------------------------------
# Gaps
# --------------------------------------------------------------------------
def find_gaps(df, direction, min_gap_pct):
    """All gaps in `df` matching the direction. idx is positional within df.

    Each gap carries the zone it left untraded: prev_close .. gap-day open.
    """
    opens = df["Open"].values
    closes = df["Close"].values
    gaps = []
    for i in range(1, len(df)):
        prev_close = closes[i - 1]
        if prev_close <= 0:
            continue
        gap_pct = (opens[i] - prev_close) / prev_close * 100
        if (direction == "up" and gap_pct >= min_gap_pct) or \
           (direction == "down" and gap_pct <= -min_gap_pct):
            gaps.append({"idx": i, "gap_pct": gap_pct,
                         "prev_close": float(prev_close),
                         "open": float(opens[i])})
    return gaps


def check_gap(df, direction, min_gap_pct, condition, lookback):
    if len(df) < 2:
        return False, "not enough data"
    sub = df.tail(lookback).reset_index(drop=True)
    highs = sub["High"].values
    lows = sub["Low"].values

    gaps = find_gaps(sub, direction, min_gap_pct)
    if not gaps:
        return False, f"no {direction} gap >= {min_gap_pct}%"

    last = gaps[-1]
    i, gap_pct, prev_close = last["idx"], last["gap_pct"], last["prev_close"]
    zone_lo, zone_hi = sorted([prev_close, last["open"]])
    if direction == "up":
        filled = bool(lows[i:].min() <= prev_close)
    else:
        filled = bool(highs[i:].max() >= prev_close)

    if condition == "price_inside":
        price = float(sub["Close"].iloc[-1])
        ok = zone_lo <= price <= zone_hi
        where = "inside" if ok else "outside"
        return ok, f"{direction} gap zone {zone_lo:.2f}-{zone_hi:.2f}, price {where}"
    if condition == "any":
        ok = True
    elif condition == "filled":
        ok = filled
    else:  # unfilled
        ok = not filled
    state = "filled" if filled else "open"
    return ok, f"{direction} gap {gap_pct:+.1f}% ({state})"


# --------------------------------------------------------------------------
# Support / Resistance
# --------------------------------------------------------------------------
def _touches(low, high, level, tolerance_pct):
    """True if the candle range [low, high] reaches `level` within tolerance."""
    if level <= 0:
        return False
    if low <= level <= high:
        return True
    dist = min(abs(low - level), abs(high - level)) / level * 100
    return dist <= tolerance_pct


def support_resistance_levels(df, lookback, swing_strength):
    """Horizontal S/R levels: swing highs = resistance, swing lows = support."""
    sub = df.tail(lookback)
    is_high, is_low = _swing_points(sub, swing_strength)
    levels = []
    for ts, price in sub["High"][is_high].items():
        levels.append({"price": float(price), "kind": "resistance", "time": ts})
    for ts, price in sub["Low"][is_low].items():
        levels.append({"price": float(price), "kind": "support", "time": ts})
    return levels


def support_trendline(df, lookback, swing_strength, anchor):
    """Diagonal trendline anchored on a major swing extreme.

    anchor='lows'  -> rising support: from the lowest swing low to the most
                      recent swing low that formed after it.
    anchor='highs' -> falling resistance: from the highest swing high to the
                      most recent swing high after it.

    Returns the two anchor points plus the line value extrapolated to the
    most recent bar, or None if fewer than two swing points exist.
    """
    sub = df.tail(lookback)
    is_high, is_low = _swing_points(sub, swing_strength)
    if anchor == "highs":
        mask, col = is_high, "High"
    else:
        mask, col = is_low, "Low"
    pts = [(pos, float(sub[col].iloc[pos]))
           for pos in range(len(sub)) if bool(mask.iloc[pos])]
    if len(pts) < 2:
        return None

    # anchor 1 = the major extreme (lowest low / highest high)
    if anchor == "highs":
        major = max(range(len(pts)), key=lambda k: pts[k][1])
    else:
        major = min(range(len(pts)), key=lambda k: pts[k][1])
    later = [p for p in pts if p[0] > pts[major][0]]
    if later:
        (x1, y1), (x2, y2) = pts[major], later[-1]
    else:
        # the major extreme is the most recent swing -> fall back to last two
        (x1, y1), (x2, y2) = pts[-2], pts[-1]
    if x2 == x1:
        return None

    slope = (y2 - y1) / (x2 - x1)
    last = len(sub) - 1
    return {
        "anchor": anchor,
        "t1": sub.index[x1], "y1": y1,
        "t2": sub.index[x2], "y2": y2,
        "t_last": sub.index[last],
        "price_now": y1 + slope * (last - x1),
    }


def check_support_resistance(df, lookback, line_types, swing_strength,
                             tolerance_pct, trendline_anchor):
    """Pass when the current candle touches a horizontal level or trendline."""
    if len(df) < 2 * swing_strength + 2:
        return False, "not enough data"
    candle = df.iloc[-1]
    low, high = float(candle["Low"]), float(candle["High"])
    touched = []
    if "horizontal" in line_types:
        for lvl in support_resistance_levels(df, lookback, swing_strength):
            if _touches(low, high, lvl["price"], tolerance_pct):
                touched.append(f"{lvl['kind']} {lvl['price']:.2f}")
    if "trendline" in line_types:
        tl = support_trendline(df, lookback, swing_strength, trendline_anchor)
        if tl is not None and _touches(low, high, tl["price_now"], tolerance_pct):
            touched.append(f"trendline {tl['price_now']:.2f}")
    if touched:
        return True, "touched " + ", ".join(touched[:3])
    return False, "no S/R touch"

# ============================ analysis ============================
"""Builds chart-ready annotations for one ticker.

Given the current config, produces candles plus every feature the bot
detects (moving averages, FVG zones, liquidity swings, range levels,
gaps, support/resistance) so the dashboard can draw them on a
TradingView Lightweight Chart with an explaining legend.
"""
import pandas as pd


MA_COLORS = ["#f59e0b", "#06b6d4", "#a855f7", "#eab308", "#ec4899"]
GREEN = "#22c55e"
RED = "#ef4444"
BLUE = "#3b82f6"
AMBER = "#f59e0b"
TRENDLINE = "#facc15"
GAP_FILL = "rgba(236,72,153,0.22)"
GAP_LINE = "#ec4899"
INTRADAY = ("15m", "30m", "60m", "1h")


def _fmt(ts, timeframe):
    ts = pd.Timestamp(ts)
    if timeframe in INTRADAY:
        return int(ts.timestamp())
    return ts.strftime("%Y-%m-%d")


def _merge_levels(levels, tol_pct=0.6, keep=7):
    """Collapse S/R levels that sit within tol_pct of each other."""
    ordered = sorted(levels, key=lambda x: x["price"])
    merged = []
    for lvl in ordered:
        if merged and abs(lvl["price"] - merged[-1]["price"]) / merged[-1]["price"] * 100 <= tol_pct:
            continue
        merged.append(lvl)
    if len(merged) > keep:  # keep the levels nearest the latest price
        merged = merged[-keep:]
    return merged


def _empty(ticker, timeframe, error):
    return {"ticker": ticker, "timeframe": timeframe, "error": error,
            "candles": [], "lines": [], "priceLines": [], "boxes": [],
            "markers": [], "trendlines": [], "legend": []}


def build_chart(config, ticker):
    chart_cfg = config.get("chart", {})
    timeframe = chart_cfg.get("timeframe", "1d")
    n = int(chart_cfg.get("candles", 250))

    df = get_data([ticker], timeframe).get(ticker)
    if df is None or df.empty:
        return _empty(ticker, timeframe, "no data for this ticker")
    df = df.tail(n)
    times = [_fmt(t, timeframe) for t in df.index]
    last_time = times[-1]

    out = _empty(ticker, timeframe, None)
    out["candles"] = [
        {"time": times[i],
         "open": round(float(df["Open"].iloc[i]), 4),
         "high": round(float(df["High"].iloc[i]), 4),
         "low": round(float(df["Low"].iloc[i]), 4),
         "close": round(float(df["Close"].iloc[i]), 4)}
        for i in range(len(df))
    ]
    crit = config.get("criteria", {})

    def legend(color, label, desc):
        out["legend"].append({"color": color, "label": label, "desc": desc})

    # --- moving averages -------------------------------------------------
    ma_cfg = crit.get("moving_average", {})
    if ma_cfg.get("mode", "off") != "off":
        seen, ci = set(), 0
        for chk in ma_cfg.get("checks", []):
            if chk.get("check") == "ma_cross":
                specs = [(chk["ma_type"], int(chk["fast_period"])),
                         (chk["ma_type"], int(chk["slow_period"]))]
            else:
                specs = [(chk["ma_type"], int(chk["period"]))]
            for ma_type, period in specs:
                if (ma_type, period) in seen:
                    continue
                seen.add((ma_type, period))
                series = moving_average(df["Close"], ma_type, period)
                pts = [{"time": times[i], "value": round(float(series.iloc[i]), 4)}
                       for i in range(len(df)) if pd.notna(series.iloc[i])]
                color = MA_COLORS[ci % len(MA_COLORS)]
                ci += 1
                out["lines"].append({"label": f"{ma_type} {period}",
                                     "color": color, "points": pts})
                legend(color, f"{ma_type} {period}", "ממוצע נע")

    # --- FVG -------------------------------------------------------------
    fvg_cfg = crit.get("fvg", {})
    if fvg_cfg.get("mode", "off") != "off":
        directions = {chk.get("direction", "bullish")
                      for chk in fvg_cfg.get("checks", [])}
        for direction in directions:
            color = ("rgba(34,197,94,0.18)" if direction == "bullish"
                     else "rgba(239,68,68,0.18)")
            open_fvgs = [f for f in find_fvgs(df, direction)
                         if not f["filled"]]
            for f in open_fvgs:
                out["boxes"].append({
                    "time1": times[f["idx"]], "time2": last_time,
                    "price1": round(f["bottom"], 4), "price2": round(f["top"], 4),
                    "color": color, "label": f"FVG {direction}",
                })
            if open_fvgs:
                legend(color.replace("0.18", "0.9"),
                       f"FVG {direction}", "פער הוגן שלא מולא")

    # --- liquidity (swing points) ---------------------------------------
    liq_cfg = crit.get("liquidity", {})
    if liq_cfg.get("mode", "off") != "off":
        strengths = {int(chk.get("strength", 5))
                     for chk in liq_cfg.get("checks", [])}
        strength = min(strengths) if strengths else 5
        is_high, is_low = _swing_points(df, strength)
        hi_idx = [i for i in range(len(df)) if bool(is_high.iloc[i])][-12:]
        lo_idx = [i for i in range(len(df)) if bool(is_low.iloc[i])][-12:]
        for i in hi_idx:
            out["markers"].append({"time": times[i], "position": "aboveBar",
                                   "color": RED, "shape": "circle",
                                   "text": "נזילות"})
        for i in lo_idx:
            out["markers"].append({"time": times[i], "position": "belowBar",
                                   "color": GREEN, "shape": "circle",
                                   "text": "נזילות"})
        if hi_idx or lo_idx:
            legend(RED, "נזילות", "נקודות סווינג שמעליהן/מתחתן יושבת נזילות")

    # --- range / equilibrium (auto dealing range) -----------------------
    rng_cfg = crit.get("range_equilibrium", {})
    if rng_cfg.get("mode", "off") != "off":
        dr = dealing_range(df, int(rng_cfg.get("swing_strength", 10)),
                               int(rng_cfg.get("max_lookback", 250)))
        if dr is not None:
            out["priceLines"] += [
                {"price": round(dr["high"], 2), "color": RED,
                 "label": f"Range High {dr['high']:.2f}"},
                {"price": round(dr["eq"], 2), "color": BLUE,
                 "label": f"EQ 50% {dr['eq']:.2f}"},
                {"price": round(dr["low"], 2), "color": GREEN,
                 "label": f"Range Low {dr['low']:.2f}"},
            ]
            out["markers"].append({
                "time": _fmt(dr["high_time"], timeframe), "position": "aboveBar",
                "color": RED, "shape": "arrowDown", "text": "Range High"})
            out["markers"].append({
                "time": _fmt(dr["low_time"], timeframe), "position": "belowBar",
                "color": GREEN, "shape": "arrowUp", "text": "Range Low"})
            legend(BLUE, "Range / Equilibrium",
                   "טווח הסווינג המשמעותי האחרון; EQ = אמצע (50%)")
            if rng_cfg.get("zone") == "equilibrium":
                band_lo, band_hi = eq_band(
                    dr, float(rng_cfg.get("eq_band_pct", 10)))
                anchor = min(dr["high_time"], dr["low_time"])
                out["boxes"].append({
                    "time1": _fmt(anchor, timeframe), "time2": last_time,
                    "price1": round(band_lo, 4), "price2": round(band_hi, 4),
                    "color": "rgba(59,130,246,0.14)", "label": "EQ band",
                })
                legend(BLUE, "אזור EQ", "רצועת ה-50% שהבוט בודק נגיעה בה")

    # --- gaps (drawn as shaded price zones, separate from FVG) ----------
    gap_cfg = crit.get("gaps", {})
    if gap_cfg.get("mode", "off") != "off":
        direction = gap_cfg.get("direction", "up")
        gaps = find_gaps(df, direction, float(gap_cfg.get("min_gap_pct", 1.0)))
        for g in gaps[-6:]:
            lo, hi = sorted([g["prev_close"], g["open"]])
            out["boxes"].append({
                "time1": times[g["idx"]], "time2": last_time,
                "price1": round(lo, 4), "price2": round(hi, 4),
                "color": GAP_FILL, "label": f"פער {g['gap_pct']:+.1f}%",
            })
        if gaps:
            legend(GAP_LINE, "פער (Gap)", "אזור הגאפ — לתפוס את הכניסה אליו")

    # --- support / resistance -------------------------------------------
    sr_cfg = crit.get("support_resistance", {})
    if sr_cfg.get("mode", "off") != "off":
        lookback = int(sr_cfg.get("lookback", 250))
        strength = int(sr_cfg.get("swing_strength", 5))
        line_types = sr_cfg.get("line_types", ["horizontal"])
        if "horizontal" in line_types:
            levels = _merge_levels(
                support_resistance_levels(df, lookback, strength))
            for lvl in levels:
                support = lvl["kind"] == "support"
                out["priceLines"].append({
                    "price": round(lvl["price"], 2),
                    "color": GREEN if support else RED,
                    "label": ("תמיכה " if support else "התנגדות ")
                             + f"{lvl['price']:.2f}",
                })
            if levels:
                legend(GREEN, "תמיכה / התנגדות", "קווים אופקיים מנקודות קיצון")
        if "trendline" in line_types:
            tl = support_trendline(df, lookback, strength,
                                       sr_cfg.get("trendline_anchor", "lows"))
            if tl is not None:
                out["trendlines"].append({
                    "color": TRENDLINE,
                    "p1": {"time": _fmt(tl["t1"], timeframe),
                           "price": round(tl["y1"], 4)},
                    "p2": {"time": _fmt(tl["t2"], timeframe),
                           "price": round(tl["y2"], 4)},
                })
                legend(TRENDLINE, "קו מגמה",
                       "קו מגמה אלכסוני מ-2 נקודות קיצון, נמתח קדימה")

    # markers must be unique per time and sorted for Lightweight Charts
    seen_times = set()
    unique = []
    for m in sorted(out["markers"], key=lambda x: str(x["time"])):
        if m["time"] in seen_times:
            continue
        seen_times.add(m["time"])
        unique.append(m)
    out["markers"] = unique
    return out

# ============================ notifier ============================
"""Telegram notifications."""
import requests

API = "https://api.telegram.org/bot{token}/sendMessage"


def send_telegram(token, chat_id, text):
    """Send a message via the Telegram Bot API. Returns (ok, detail)."""
    if not token or not chat_id:
        return False, "telegram not configured (missing token or chat id)"
    try:
        resp = requests.post(
            API.format(token=token),
            json={
                "chat_id": chat_id,
                "text": text,
                "parse_mode": "HTML",
                "disable_web_page_preview": True,
            },
            timeout=20,
        )
        if resp.status_code == 200:
            return True, "sent"
        return False, f"telegram error {resp.status_code}: {resp.text[:200]}"
    except requests.RequestException as exc:
        return False, f"request failed: {exc}"

# ============================ scanner ============================
"""Scan orchestration: download data, evaluate every ticker, score, notify."""
import threading
from datetime import datetime


# Hebrew labels used in Telegram messages and (as a fallback) the UI.
CRITERION_LABELS = {
    "moving_average": "ממוצעים נעים",
    "fvg": "FVG",
    "liquidity": "נזילות",
    "range_equilibrium": "Range/EQ",
    "gaps": "פערים",
    "support_resistance": "תמיכה/התנגדות",
}


# --------------------------------------------------------------------------
# Shared scan state (read by the dashboard via /api/scan/status)
# --------------------------------------------------------------------------
class ScanState:
    def __init__(self):
        self.lock = threading.Lock()
        self.running = False
        self.phase = "idle"          # idle | downloading | evaluating | done | error
        self.progress = 0
        self.total = 0
        self.results = []
        self.last_run = None
        self.error = None
        self.errors_count = 0
        self.universe_size = 0

    def snapshot(self):
        with self.lock:
            return {
                "running": self.running,
                "phase": self.phase,
                "progress": self.progress,
                "total": self.total,
                "results": self.results,
                "last_run": self.last_run,
                "error": self.error,
                "errors_count": self.errors_count,
                "universe_size": self.universe_size,
            }


STATE = ScanState()


# --------------------------------------------------------------------------
# Per-criterion evaluation
# --------------------------------------------------------------------------
def _df(data, timeframe, ticker):
    return data.get(timeframe, {}).get(ticker)


def _multi(checks, match, evaluate_one):
    """Combine a list of sub-checks with all/any logic."""
    if not checks:
        return False, "no checks configured"
    results = [evaluate_one(chk) for chk in checks]
    oks = [r[0] for r in results]
    detail = " | ".join(r[1] for r in results)
    passed = all(oks) if match == "all" else any(oks)
    return passed, detail


def eval_moving_average(cfg, data, ticker):
    def one(chk):
        df = _df(data, chk.get("timeframe", "1d"), ticker)
        if df is None or df.empty:
            return False, f"{chk.get('timeframe', '1d')}: no data"
        kind = chk.get("check")
        if kind == "price_vs_ma":
            return check_price_vs_ma(df, chk["ma_type"], int(chk["period"]),
                                         chk["condition"])
        if kind == "ma_cross":
            return check_ma_cross(df, chk["ma_type"], int(chk["fast_period"]),
                                      int(chk["slow_period"]), chk["direction"],
                                      int(chk.get("within_bars", 10)))
        if kind == "price_near_ma":
            return check_price_near_ma(df, chk["ma_type"], int(chk["period"]),
                                           float(chk["tolerance_pct"]))
        return False, "unknown MA check"

    return _multi(cfg.get("checks", []), cfg.get("match", "all"), one)


def eval_fvg(cfg, data, ticker):
    def one(chk):
        df = _df(data, chk.get("timeframe", "1d"), ticker)
        if df is None or df.empty:
            return False, f"{chk.get('timeframe', '1d')}: no data"
        return check_fvg(df, chk["direction"], chk["condition"],
                             int(chk.get("lookback", 60)))

    return _multi(cfg.get("checks", []), cfg.get("match", "all"), one)


def eval_liquidity(cfg, data, ticker):
    def one(chk):
        df = _df(data, chk.get("timeframe", "1d"), ticker)
        if df is None or df.empty:
            return False, f"{chk.get('timeframe', '1d')}: no data"
        return check_liquidity(df, int(chk.get("strength", 5)),
                                   int(chk.get("lookback", 120)), chk["condition"],
                                   int(chk.get("recency", 5)))

    return _multi(cfg.get("checks", []), cfg.get("match", "all"), one)


def eval_range(cfg, data, ticker):
    df = _df(data, cfg.get("timeframe", "1d"), ticker)
    if df is None or df.empty:
        return False, "no data"
    return check_range(df, int(cfg.get("swing_strength", 10)),
                           int(cfg.get("max_lookback", 250)),
                           cfg.get("zone", "discount"),
                           float(cfg.get("eq_band_pct", 10)),
                           cfg.get("eq_match", "close"))


def eval_gaps(cfg, data, ticker):
    df = _df(data, cfg.get("timeframe", "1d"), ticker)
    if df is None or df.empty:
        return False, "no data"
    return check_gap(df, cfg.get("direction", "up"),
                         float(cfg.get("min_gap_pct", 1.0)),
                         cfg.get("condition", "unfilled"),
                         int(cfg.get("lookback", 30)))


def eval_support_resistance(cfg, data, ticker):
    df = _df(data, cfg.get("timeframe", "1d"), ticker)
    if df is None or df.empty:
        return False, "no data"
    return check_support_resistance(
        df, int(cfg.get("lookback", 250)),
        cfg.get("line_types", ["horizontal"]),
        int(cfg.get("swing_strength", 5)),
        float(cfg.get("tolerance_pct", 1.0)),
        cfg.get("trendline_anchor", "lows"))


EVALUATORS = {
    "moving_average": eval_moving_average,
    "fvg": eval_fvg,
    "liquidity": eval_liquidity,
    "range_equilibrium": eval_range,
    "gaps": eval_gaps,
    "support_resistance": eval_support_resistance,
}


# --------------------------------------------------------------------------
# Ticker scoring
# --------------------------------------------------------------------------
def collect_timeframes(config):
    """Every timeframe referenced by an active criterion."""
    timeframes = set()
    for name, cfg in config.get("criteria", {}).items():
        if cfg.get("mode", "off") == "off":
            continue
        if name in ("moving_average", "fvg", "liquidity"):
            for chk in cfg.get("checks", []):
                timeframes.add(chk.get("timeframe", "1d"))
        else:
            timeframes.add(cfg.get("timeframe", "1d"))
    return sorted(timeframes) or ["1d"]


def _last_price(data, ticker):
    for timeframe in ("1d", "1h", "60m", "1wk", "1mo", "30m", "15m"):
        df = _df(data, timeframe, ticker)
        if df is not None and not df.empty:
            return round(float(df["Close"].iloc[-1]), 2)
    for tf_map in data.values():
        df = tf_map.get(ticker)
        if df is not None and not df.empty:
            return round(float(df["Close"].iloc[-1]), 2)
    return None


def evaluate_ticker(config, data, ticker):
    breakdown = []
    score = 0
    max_bonus = 0
    mandatory_ok = True

    for name, cfg in config.get("criteria", {}).items():
        mode = cfg.get("mode", "off")
        if mode == "off" or name not in EVALUATORS:
            continue
        passed, detail = EVALUATORS[name](cfg, data, ticker)
        weight = int(cfg.get("weight", 1))
        if mode == "bonus":
            max_bonus += weight
            if passed:
                score += weight
        elif mode == "mandatory" and not passed:
            mandatory_ok = False
        breakdown.append({
            "criterion": name,
            "label": CRITERION_LABELS.get(name, name),
            "mode": mode,
            "passed": passed,
            "detail": detail,
            "weight": weight,
        })

    threshold = min(int(config.get("min_score", 0)), max_bonus)
    included = mandatory_ok and score >= threshold
    return {
        "ticker": ticker,
        "price": _last_price(data, ticker),
        "score": score,
        "max_bonus": max_bonus,
        "mandatory_ok": mandatory_ok,
        "included": included,
        "breakdown": breakdown,
    }


def analyze_ticker(config, ticker):
    """Evaluate a single ticker against the config (used by the test page)."""
    timeframes = collect_timeframes(config)
    data = {tf: get_data([ticker], tf) for tf in timeframes}
    return evaluate_ticker(config, data, ticker)


# --------------------------------------------------------------------------
# Scan runner
# --------------------------------------------------------------------------
def run_scan_sync():
    """Run a full scan. Safe to call from a thread or the scheduler."""
    with STATE.lock:
        if STATE.running:
            return
        STATE.running = True
        STATE.phase = "starting"
        STATE.error = None
        STATE.progress = 0
        STATE.total = 0

    try:
        config = load_config()
        tickers = resolve_universe(config.get("universe", {}))
        with STATE.lock:
            STATE.universe_size = len(tickers)
        if not tickers:
            raise ValueError("universe is empty - add tickers in the dashboard")

        timeframes = collect_timeframes(config)
        with STATE.lock:
            STATE.phase = "downloading"
            STATE.total = len(timeframes)

        data = {}
        for idx, timeframe in enumerate(timeframes):
            data[timeframe] = get_data(tickers, timeframe)
            with STATE.lock:
                STATE.progress = idx + 1

        with STATE.lock:
            STATE.phase = "evaluating"
            STATE.total = len(tickers)
            STATE.progress = 0

        results = []
        errors = 0
        for idx, ticker in enumerate(tickers):
            try:
                outcome = evaluate_ticker(config, data, ticker)
                if outcome["included"]:
                    results.append(outcome)
            except Exception:  # noqa: BLE001 - one bad ticker must not abort the scan
                errors += 1
            with STATE.lock:
                STATE.progress = idx + 1

        results.sort(key=lambda r: (r["score"], r["ticker"]), reverse=True)
        with STATE.lock:
            STATE.results = results
            STATE.errors_count = errors
            STATE.last_run = datetime.now().isoformat(timespec="seconds")
            STATE.phase = "done"

        _notify(config, results)
    except Exception as exc:  # noqa: BLE001
        with STATE.lock:
            STATE.error = str(exc)
            STATE.phase = "error"
    finally:
        with STATE.lock:
            STATE.running = False


def start_scan():
    """Start a scan in a background thread (no-op if one is already running)."""
    with STATE.lock:
        if STATE.running:
            return False
    threading.Thread(target=run_scan_sync, daemon=True).start()
    return True


# --------------------------------------------------------------------------
# Telegram notification
# --------------------------------------------------------------------------
def _chunks(text, size=3900):
    lines = text.split("\n")
    buf = ""
    for line in lines:
        if len(buf) + len(line) + 1 > size:
            if buf:
                yield buf
            buf = line
        else:
            buf = f"{buf}\n{line}" if buf else line
    if buf:
        yield buf


def _notify(config, results):
    telegram = config.get("telegram", {})
    if not telegram.get("enabled"):
        return
    stamp = datetime.now().strftime("%Y-%m-%d %H:%M")
    if not results:
        message = f"\U0001F50D Stock Scanner ({stamp})\nNo stocks matched the filter."
    else:
        lines = [f"\U0001F50D <b>Stock Scanner</b> - {len(results)} matches ({stamp})", ""]
        for r in results[:50]:
            price = f"${r['price']:.2f}" if r["price"] is not None else "-"
            lines.append(f"<b>{r['ticker']}</b> {price}  score {r['score']}/{r['max_bonus']}")
        message = "\n".join(lines)
    for chunk in _chunks(message):
        send_telegram(telegram.get("bot_token"), telegram.get("chat_id"), chunk)

# ============================ scheduler ============================
"""Optional scheduled (end-of-day) scans driven by config.schedule."""
from apscheduler.schedulers.background import BackgroundScheduler
from apscheduler.triggers.cron import CronTrigger


_scheduler = None
_job = None


def init_scheduler():
    global _scheduler
    if _scheduler is None:
        _scheduler = BackgroundScheduler()
        _scheduler.start()
    reschedule(load_config())


def shutdown_scheduler():
    if _scheduler is not None:
        _scheduler.shutdown(wait=False)


def reschedule(config):
    """Apply the schedule section of the config (called on every save)."""
    global _job
    if _scheduler is None:
        return
    if _job is not None:
        try:
            _job.remove()
        except Exception:  # noqa: BLE001
            pass
        _job = None

    schedule = config.get("schedule", {})
    if not schedule.get("enabled"):
        return
    try:
        hour, minute = str(schedule.get("time", "16:30")).split(":")
        trigger = CronTrigger(
            day_of_week="mon-fri",
            hour=int(hour),
            minute=int(minute),
            timezone=schedule.get("timezone", "America/New_York"),
        )
        _job = _scheduler.add_job(run_scan_sync, trigger, id="scheduled_scan",
                                  replace_existing=True)
    except Exception:  # noqa: BLE001 - a bad schedule must not crash the app
        _job = None

# ============================ web app ============================
import base64
from contextlib import asynccontextmanager

from fastapi import FastAPI, Request
from fastapi.responses import HTMLResponse, Response

_DASHBOARD_HTML = base64.b64decode("").decode("utf-8")
_STYLE_CSS = base64.b64decode("").decode("utf-8")
_APP_JS = base64.b64decode("").decode("utf-8")
_LWC_JS = base64.b64decode("").decode("utf-8")


@asynccontextmanager
async def lifespan(_app):
    init_scheduler()
    yield
    shutdown_scheduler()


app = FastAPI(title="Stock Scanner Bot", lifespan=lifespan)


@app.get("/", response_class=HTMLResponse)
def index():
    return _DASHBOARD_HTML


@app.get("/static/style.css")
def _css():
    return Response(_STYLE_CSS, media_type="text/css")


@app.get("/static/app.js")
def _js():
    return Response(_APP_JS, media_type="application/javascript")


@app.get("/static/lightweight-charts.js")
def _lwc():
    return Response(_LWC_JS, media_type="application/javascript")


@app.get("/api/config")
def get_config():
    return load_config()


@app.post("/api/config")
async def post_config(request: Request):
    cfg = await request.json()
    save_config(cfg)
    reschedule(cfg)
    return {"status": "saved"}


@app.post("/api/scan")
def post_scan():
    started = start_scan()
    return {"status": "started" if started else "already_running"}


@app.get("/api/scan/status")
def get_scan_status():
    return STATE.snapshot()


@app.get("/api/chart/{ticker}")
def get_chart(ticker: str, timeframe: str = None):
    config = load_config()
    if timeframe:
        config.setdefault("chart", {})["timeframe"] = timeframe
    return build_chart(config, ticker.upper())


@app.post("/api/test")
async def post_test(request: Request):
    body = await request.json()
    ticker = (body.get("ticker") or "").strip().upper()
    if not ticker:
        return {"error": "missing ticker"}
    timeframe = body.get("timeframe", "1d")
    selected = set(body.get("criteria", []))
    config = load_config()
    config.setdefault("chart", {})["timeframe"] = timeframe
    for name, ccfg in config.get("criteria", {}).items():
        if name in selected:
            if ccfg.get("mode", "off") == "off":
                ccfg["mode"] = "bonus"
        else:
            ccfg["mode"] = "off"
    return {"ticker": ticker, "evaluation": analyze_ticker(config, ticker),
            "chart": build_chart(config, ticker)}


@app.post("/api/cache/clear")
def post_clear_cache():
    clear_cache()
    return {"status": "cleared"}


@app.post("/api/telegram/test")
def post_telegram_test():
    telegram = load_config().get("telegram", {})
    ok, detail = send_telegram(telegram.get("bot_token"),
                               telegram.get("chat_id"),
                               "Stock Scanner Bot - test message")
    return {"ok": ok, "message": detail}


if __name__ == "__main__":
    import uvicorn
    uvicorn.run(app, host="127.0.0.1", port=8000)
